{
  "correction_rules": [
    "When sentiment is negative (≤ 0), reduce forecasted prices by 5-10% to account for downward pressure.",
    "After a price spike (≥ 10% above recent mean), apply a 10-15 day lag correction to avoid overshoot.",
    "If true outcome consistently exceeds forecast by > 3% over 3 consecutive days, adjust forecast upward by 2-5% to capture mean reversion.",
    "In periods with rising sentiment (≥ 0.5), increase forecast sensitivity to recent price momentum, but cap at +10% above prior peak.",
    "If forecast consistently underestimates true outcome by > 5% over 5 days, apply a 3-5% upward bias correction to align with recent trend.",
    "For long-term (30-day) forecasts, reduce volatility in early periods if sentiment is neutral or negative, to avoid overreacting to short-term noise."
  ]
}
